function validate([nums]) {
  if (nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 100000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is an integer from -10^9 to 10^9.';
  if (new Set(nums).size !== nums.length) return 'All values in nums must be distinct.';
  return null;
}

