function countOperationsToEmptyArray(nums) {
  const n = nums.length;
  const order = Array.from({ length: n }, (_, i) => i);
  order.sort((a, b) => nums[a] - nums[b]);
  const tree = new Array(n + 1).fill(0);

  const update = (index, delta) => {
    for (let j = index + 1; j <= n; j += j & -j) {
      tree[j] += delta;
    }
  };
  const countUpTo = (index) => {
    let total = 0;
    for (let j = index + 1; j > 0; j -= j & -j) {
      total += tree[j];
    }
    return total;
  };

  for (let i = 0; i < n; i++) {
    update(i, 1);
  }
  let operations = 0;
  let prev = -1;
  for (const index of order) {
    if (index > prev) {
      operations += countUpTo(index) - countUpTo(prev);
    } else {
      operations += countUpTo(n - 1) - countUpTo(prev) + countUpTo(index);
    }
    update(index, -1);
    prev = index;
  }
  return operations;
}

