function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? int(1, 10) : 2000;
  const limit = size === 'small' && rand() < 0.7 ? 20 : 1000000000;
  const seen = new Set();
  const nums = [];
  while (nums.length < n) {
    const v = int(-limit, limit);
    if (seen.has(v)) continue;
    seen.add(v);
    nums.push(v);
  }
  const shape = rand();
  if (shape < 0.15) {
    nums.sort((a, b) => b - a);
  } else if (shape < 0.25) {
    nums.sort((a, b) => a - b);
  } else if (shape < 0.4) {
    nums.sort((a, b) => a - b);
    const cut = int(0, n - 1);
    return [nums.slice(cut).concat(nums.slice(0, cut))];
  }
  return [nums];
}
